import { AxisIdToScaleMap } from '../context/XYChartXScalesContext.js';
import { AxisId, XYChartScale } from '../types/xy-chart.js';

export function getScaleByAxisId(
  id: AxisId,
  idToScaleMap: AxisIdToScaleMap,
): XYChartScale {
  const scale = id ? idToScaleMap.get(id) : undefined;

  if (scale === undefined) {
    throw new Error(`Scale not found for axis id ${id}`);
  }
  return scale;
}
